--
-- Table structure for table `intervention_records`
--

DROP TABLE IF EXISTS `intervention_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `intervention_records` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `abnormal_id` bigint NOT NULL COMMENT '对应异常学生表ID',
  `teacher_id` bigint NOT NULL COMMENT '干预老师ID',
  `title` varchar(100) NOT NULL COMMENT '干预主题',
  `content` text NOT NULL COMMENT '干预详情',
  `record_date` date NOT NULL COMMENT '干预日期',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `abnormal_id` (`abnormal_id`),
  KEY `teacher_id` (`teacher_id`),
  CONSTRAINT `intervention_records_ibfk_1` FOREIGN KEY (`abnormal_id`) REFERENCES `abnormal_students` (`id`),
  CONSTRAINT `intervention_records_ibfk_2` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生干预记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

