INSERT INTO `intervention_records` VALUES (1,1,1,'一对一沟通疏导','耐心倾听学生内心想法，鼓励主动表达，引导融入同学','2026-04-25','2026-04-28 17:52:35'),(2,1,1,'家校沟通配合','联系家长了解家庭环境，共同制定社交引导方案','2026-04-26','2026-04-28 17:52:35'),(3,2,1,'课堂行为纠正','提醒专注听课，采用分段任务提升注意力','2026-04-24','2026-04-28 17:52:35'),(4,2,1,'学习习惯培养','制定每日专注训练计划，逐步提升效率','2026-04-25','2026-04-28 17:52:35'),(5,3,1,'鼓励课堂发言','创造轻松环境，鼓励小声表达，逐步建立自信','2026-04-20','2026-04-28 17:52:35'),(6,3,1,'小组活动引导','安排温和同伴带动，减少独处情况','2026-04-21','2026-04-28 17:52:35'),(7,4,1,'长期心理关怀','持续关注情绪状态，提供安全感与支持','2026-04-18','2026-04-28 17:52:35'),(8,4,1,'同伴结对帮助','安排热心同学陪伴，提升社交意愿','2026-04-19','2026-04-28 17:52:35'),(9,5,1,'情绪安抚引导','关注情绪变化，鼓励表达需求','2026-04-25','2026-04-28 17:52:35'),(10,6,10,'注意力专项训练','通过小游戏、分段任务提升专注度','2026-04-24','2026-04-28 17:52:35'),(11,7,2,'自信心建立辅导','正向鼓励为主，减少批评压力','2026-04-23','2026-04-28 17:52:35'),(12,8,9,'心理状态观察','持续关注情绪变化，及时疏导负面情绪','2026-04-22','2026-04-28 17:52:35'),(13,9,6,'社交能力培养','创造小组互动机会，引导主动交流','2026-04-21','2026-04-28 17:52:35'),(14,10,4,'减压心理辅导','降低学习压力，调整目标预期','2026-04-20','2026-04-28 17:52:35'),(15,11,12,'情绪管理训练','学习冷静方法，提升自控能力','2026-04-19','2026-04-28 17:52:35'),(16,12,12,'自信心提升计划','多肯定、多鼓励，强化自我认同','2026-04-18','2026-04-28 17:52:35'),(17,13,5,'学习兴趣激发','寻找兴趣点，降低任务难度','2026-04-17','2026-04-28 17:52:35'),(18,14,5,'课堂表达训练','从轻声回答开始，逐步适应公开表达','2026-04-16','2026-04-28 17:52:35'),(19,15,5,'班级规则教育','明确纪律要求，强化规则意识','2026-04-15','2026-04-28 17:52:35'),(20,16,7,'新环境适应指导','帮助熟悉环境，建立安全感','2026-04-14','2026-04-28 17:52:35'),(21,17,14,'时间管理训练','制定计划，分解任务，按时完成','2026-04-13','2026-04-28 17:52:35'),(22,18,8,'矛盾调解引导','学习沟通方式，改善同学关系','2026-04-12','2026-04-28 17:52:35'),(23,19,8,'独立性培养','鼓励自主完成任务，减少依赖','2026-04-11','2026-04-28 17:52:35'),(24,20,11,'沟通鼓励计划','耐心引导，创造安全表达环境','2026-04-10','2026-04-28 17:52:35'),(25,21,11,'放松训练辅导','学习呼吸放松、情绪调节方法','2026-04-09','2026-04-28 17:52:35'),(26,22,11,'深度心理关怀','持续陪伴，逐步打开心扉','2026-04-08','2026-04-28 17:52:35'),(27,23,11,'纪律规范教育','明确课堂要求，及时纠正行为','2026-04-07','2026-04-28 17:52:35'),(28,24,11,'学习目标激励','设定小目标，