--
-- Table structure for table `predictions`
--

DROP TABLE IF EXISTS `predictions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `predictions` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `teacher_id` bigint NOT NULL COMMENT '教师ID',
  `class_id` bigint NOT NULL COMMENT '班级ID',
  `scene` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '预测场景',
  `decision` text COLLATE utf8mb4_general_ci COMMENT '决策描述',
  `result` json DEFAULT NULL COMMENT '预测结果',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `teacher_id` (`teacher_id`),
  KEY `class_id` (`class_id`),
  CONSTRAINT `predictions_ibfk_1` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`),
  CONSTRAINT `predictions_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='模拟预测记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `predictions`
--

LOCK TABLES `predictions` WRITE;
/*!40000 ALTER TABLE `predictions` DISABLE KEYS */;
INSERT INTO `predictions` VALUES (1,1,1,'课堂氛围','采用小组讨论形式，增加互动环节','{\"risk\": \"低\", \"score\": 85, \"suggestion\": \"可适当增加竞赛元素\"}','2026-04-28 20:21:50'),(2,2,2,'作业完成率','分层布置作业，设置基础与拓展任务','{\"risk\": \"中\", \"score\": 78, \"suggestion\": \"加强对学困生的一对一辅导\"}','2026-04-28 20:21:50'),(3,3,3,'课堂纪律','采用积分奖励制，设置课堂表现榜','{\"risk\": \"低\", \"score\": 90, \"suggestion\": \"积分可兑换班级小奖品\"}','2026-04-28 20:21:50'),(4,4,4,'课堂氛围','引入多媒体互动，使用教学游戏','{\"risk\": \"低\", \"score\": 82, \"suggestion\": \"注意控制游戏时间，避免喧宾夺主\"}','2026-04-28 20:21:50'),(5,5,5,'作业完成率','建立作业打卡群，每日提醒提交','{\"risk\": \"中\", \"score\": 75, \"suggestion\": \"可增加同伴互评环节\"}','2026-04-28 20:21:50'),(6,6,6,'课堂纪律','制定班级公约，明确奖惩规则','{\"risk\": \"低\", \"score\": 88, \"suggestion\": \"规则执行需公平公正\"}','2026-04-28 20:21:50'),(7,7,7,'课堂氛围','组织课前分享，鼓励学生表达','{\"risk\": \"低\", \"score\": 80, \"suggestion\": \"可设置主题分享，降低学生压力\"}','2026-04-28 20:21:50'),(8,8,8,'作业完成率','设置弹性提交时间，提供线上答疑','{\"risk\": \"中\", \"score\": 72, \"suggestion\": \"需明确弹性时间的截止节点\"}','2026-04-28 20:21:50'),(9,9,9,'课堂纪律','采用无声手势提醒，减少课堂中断','{\"risk\": \"低\", \"score\": 86, \"suggestion\": \"手势需提前和学生约定好\"}','2026-04-28 20:21:50'),(10,10,10,'课堂氛围','引入翻转课堂，让学生讲课','{\"risk\": \"中\", \"score\": 79, \"suggestion\": \"需提前培训学生讲课的基本方法\"}','2026-04-28 20:21:50'),(11,11,11,'作业完成率','设置小组作业，以组为单位提交','{\"risk\": \"低\", \"score\": 83, \"suggestion\": \"需明确组内分工，避免搭便车\"}','2026-04-28 20:21:50'),(12,12,12,'课堂纪律','采用班级日志记录，每周复盘','{\"risk\": \"低\", \"score\": 87, \"suggestion\": \"复盘时多鼓励，少批评\"}','2026-04-28 20:21:50'),(13,13,13,'课堂氛围','开展课堂小实验，增强体验感','{\"risk\": \"中\", \"score\": 84, \"suggestion\": \"需提前做好安全预案\"}','2026-04-28 20:21:50'),(14,14,14,'作业完成率','提供作业模板和范例，降低难度','{\"risk\": \"中\", \"score\": 76, \"suggestion\": \"范例不宜过多，避免限制学生思路\"}','2026-04-28 20:21:50'),(15,15,15,'课堂纪律','设置课堂监督员，互相提醒','{\"risk\": \"低\", \"score\": 81, \"suggestion\": \"监督员需定期轮换，避免矛盾\"}','2026-04-28 20:21:50'),(16,1,1,'作业完成率','分层作业+线上答疑双管齐下','{\"risk\": \"低\", \"score\": 89, \"suggestion\": \"可对完成优秀的学生进行表扬\"}','2026-04-28 20:21:50'),(17,2,2,'课堂纪律','积分奖励制+班级公约并行','{\"risk\": \"低\", \"score\": 88, \"suggestion\": \"积分奖励可与期末评优挂钩\"}','2026-04-28 20:21:50'),(18,3,3,'课堂氛围','小组讨论+多媒体互动结合','{\"risk\": \"低\", \"score\": 86, \"suggestion\": \"需提前分好小组，固定座位\"}','2026-04-28 20:21:50'),(19,4,4,'课堂纪律','无声手势+课堂日志双重管理','{\"risk\": \"低\", \"score\": 84, \"suggestion\": \"课堂日志需定期公开，接受监督\"}','2026-04-28 20:21:50'),(20,5,5,'课堂氛围','课前分享+翻转课堂交替使用','{\"risk\": \"中\", \"score\": 80, \"suggestion\": \"需控制分享和讲课的时间占比\"}','2026-04-28 20:21:50');
/*!40000 ALTER TABLE `predictions` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `replies`
--

DROP TABLE IF EXISTS `replies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `replies` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `post_id` bigint NOT NULL COMMENT '帖子ID',
  `author_id` bigint NOT NULL COMMENT '作者ID',
  `content` text COLLATE utf8mb4_general_ci NOT NULL COMMENT '内容',
  `likes` int DEFAULT '0' COMMENT '点赞数',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `post_id` (`post_id`),
  KEY `author_id` (`author_id`),
  CONSTRAINT `replies_ibfk_1` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`),
  CONSTRAINT `replies_ibfk_2` FOREIGN KEY (`author_id`) REFERENCES `teachers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='回复表';
/*!40101 SET character_set_client = @saved_cs_client */;

