--
-- Table structure for table `student_pets`
--

DROP TABLE IF EXISTS `student_pets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_pets` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `pet_id` bigint NOT NULL COMMENT '宠物ID',
  `pet_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '宠物昵称',
  `pet_exp` int DEFAULT '0' COMMENT '宠物经验值',
  `pet_level` enum('S','A','B','C') COLLATE utf8mb4_general_ci DEFAULT 'B' COMMENT '宠物当前等级',
  `is_active` tinyint DEFAULT '1' COMMENT '是否启用',
  `obtained_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '获得时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `student_id` (`student_id`),
  KEY `pet_id` (`pet_id`),
  CONSTRAINT `student_pets_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `student_pets_ibfk_2` FOREIGN KEY (`pet_id`) REFERENCES `pets` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='学生宠物关联表';
/*!40101 SET character_set_client = @saved_cs_client */;

