--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `students` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `student_no` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学号',
  `password` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码(加密)',
  `class_id` bigint DEFAULT NULL COMMENT '班级ID',
  `gender` enum('male','female') COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '性别(male/female)',
  `avatar` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '头像URL',
  `email` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号',
  `points` int DEFAULT '0' COMMENT '积分',
  `task_completion_rate` int DEFAULT '0' COMMENT '任务完成率(%)',
  `mood_index` int DEFAULT '5' COMMENT '情绪指数(1-5)',
  `mood_status` enum('良好','关注','异常') COLLATE utf8mb4_general_ci DEFAULT '良好' COMMENT '心理状态',
  `personality` text COLLATE utf8mb4_general_ci COMMENT '性格分析',
  `is_checkin` tinyint DEFAULT '0' COMMENT '今日是否签到',
  `checkin_date` date DEFAULT NULL COMMENT '最后签到日期',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_no` (`student_no`),
  KEY `fk_students_class` (`class_id`),
  CONSTRAINT `fk_students_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`),
  CONSTRAINT `students_ibfk_1` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=361 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `students`
--

LOCK TABLES `students` WRITE;
/*!40000 ALTER TABLE `students` DISABLE KEYS */;
